```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock once; this is the instant the heartbeat reports.
        let seconds: u64 = wall_clock::now().seconds;

        // One permitted fetch. A transport failure comes back as a value and
        // counts as zero characters; an out-of-allowlist host traps at the
        // boundary and is not handled here.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat seconds={} fetched={}", seconds, fetched);

        // Report the notifier's actual outcome rather than asserting it.
        let notified: bool = notifier::notify(&message);

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
